#define NOMINMAX
#include "slot_checkpoint_file.cuh"
#include "dual_state_initialization.hpp"
#include "bpe_pilot_reader.hpp"
#include "tokenizer_file.hpp"
#include <cstdio>
int main(int argc,char**argv){try{using namespace tao::dual;constexpr unsigned budget=100;std::string th;tao::text::load_tokenizer("build/formal_tokenizer.bbp",th);std::ifstream f("build/bpe_pilot_train.bin",std::ios::binary);std::string raw((std::istreambuf_iterator<char>(f)),{});auto dh=tao::text::sha256(raw);std::istringstream input(raw);auto docs=tao::data::read_bpe_pilot(input,th);SortedGpuTrainer tr(initialize(Config{},713));SequenceSlots slots(tr,4);tao::data::PilotCursor cursor(std::move(docs),4,false);auto identity=checkpoint_identity(tr.graph.c,dh,th,budget)+"block256-slots4-accum8-linear2-cosine98-peak0.0003-min0.00003\n";if(argc>1){auto snap=load_slot_file(argv[1],identity,capture(slots,cursor),cursor);restore(snap,slots,cursor);}if(tr.steps>=budget)throw std::runtime_error("budget complete");size_t n=0,positions=0;double loss=0;for(int r=0;r<8;++r)for(unsigned k=0;k<4;++k){tao::data::Work work;if(!cursor.take(k,256,work))continue;slots.begin(k,work.reset);size_t local=0;auto&t=cursor.docs[work.doc];for(size_t i=work.begin;i<work.end;++i){auto y=tr.graph.step(t[i-1].id);float v=seed_loss(y,t[i].id,t[i].loss);if(!std::isfinite(v))throw std::runtime_error("loss");loss+=v;local+=t[i].loss;++positions;}slots.finish(local!=0);n+=local;printf("chunk=%d slot=%u cumulative_supervised=%zu\n",r,k,n);fflush(stdout);}if(!n)throw std::runtime_error("epoch exhausted/no supervised targets");unsigned step=tr.steps+1;float lr=step<=2?.0003f*step/2:float(.00003+.00027*.5*(1+std::cos(3.141592653589793*(step-2)/98)));float norm=tr.update(n,lr);auto path="build/yaoyao_train_step_"+std::to_string(tr.steps)+".scp";save_slot_file(capture(slots,cursor),path,identity);CpuModel cpu(tr.graph.c);for(auto&kv:cpu.w)kv.second=tr.graph.w.at(kv.first)->value.host();save_bundle(cpu,"build/yaoyao_train_step_"+std::to_string(tr.steps)+".dsb",th);printf("SAVED step=%u positions=%zu supervised=%zu train_preupdate_NLL=%.7f lr=%.9g norm=%.6f checkpoint=%s\n",tr.steps,positions,n,loss/n,lr,norm,path.c_str());return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
